import CommunityBulkStart from './CommunityBulkStart.jsx';
import { useEffect, useMemo, useRef, useState } from "react";
import { FitAddon } from "@xterm/addon-fit";
import { Terminal } from "@xterm/xterm";
import "./xterm.css";
