const TABS = [
  ["overview", "개요", "compute"], ["instances", "인스턴스", "compute"], ["volumes", "볼륨", "compute"],
  ["networks", "네트워크", "network"], ["routers", "라우터", "network"], ["floatingIps", "유동 IP", "network"], ["securityGroups", "보안그룹", "network"],
  ["dns", "도메인", "service"], ["loadBalancers", "로드밸런서", "service"], ["services", "공유·예약·알림", "service"], ["actions", "작업 내역", "operation"],
];
const EMPTY = { instances:[], volumes:[], networks:[], subnets:[], routers:[], floatingIps:[], securityGroups:[], ports:[], flavors:[], loadBalancerAvailable:false, loadBalancers:[], loadBalancerListeners:[], loadBalancerPools:[], loadBalancerMembers:[], loadBalancerHealthMonitors:[], dnsAvailable:false, dnsZones:[], dnsRecordsets:[], alarmAvailable:false, alarms:[], reservationAvailable:false, reservations:[], shareAvailable:false, shares:[], shareTypes:[], quota:{metrics:{}}, warnings:[] };
const won = new Intl.NumberFormat("ko-KR");
function names(values){return [...new Set((values||[]).map((v)=>String(v||"").trim()).filter(Boolean))];}
function flavorSpec(flavor,platformStatus={}){const normalized=String(flavor||"").toLowerCase();const configured=platformStatus?.pocFlavorSpecs?.[flavor]||{};if(Number(configured.vcpu)>0&&Number(configured.ramGb)>0)return {vcpu:Number(configured.vcpu),ramGb:Number(configured.ramGb),diskGb:Number(configured.diskGb||0)||(normalized.includes("tiny")?20:normalized.includes("medium")?80:normalized.includes("large")?160:50)};if(normalized.includes("tiny"))return {vcpu:1,ramGb:2,diskGb:20};if(normalized.includes("small"))return {vcpu:2,ramGb:4,diskGb:50};if(normalized.includes("medium"))return {vcpu:4,ramGb:8,diskGb:80};if(normalized.includes("large"))return {vcpu:8,ramGb:16,diskGb:160};return {vcpu:1,ramGb:2,diskGb:20};}
function liveFlavorSpec(flavor,snapshot={},platformStatus={}){const live=(snapshot.flavors||[]).find((item)=>item.name===flavor);if(live)return live;const fallback=flavorSpec(flavor,platformStatus);return {name:flavor,vcpus:fallback.vcpu,ramMb:fallback.ramGb*1024,diskGb:fallback.diskGb,ephemeralGb:0,swapMb:0,extraSpecs:{}};}
function flavorLabel(flavor,snapshot={},platformStatus={}){const spec=liveFlavorSpec(flavor,snapshot,platformStatus);return `${flavor} · ${spec.vcpus} vCPU / ${Number(spec.ramMb||0)/1024}GB RAM / ${spec.diskGb}GB Disk`;}
function FlavorDetails({flavor,snapshot,platformStatus}){if(!flavor)return null;const spec=liveFlavorSpec(flavor,snapshot,platformStatus);const extras=Object.entries(spec.extraSpecs||{}).sort(([a],[b])=>a.localeCompare(b));return <div className="mini-horizon-flavor-details"><span>{spec.vcpus} vCPU</span><span>{Number(spec.ramMb||0)/1024}GB RAM</span><span>{spec.diskGb}GB 루트 디스크</span><span>{spec.ephemeralGb||0}GB 임시 디스크</span><span>{spec.swapMb||0}MB Swap</span>{extras.length?<code>{extras.map(([key,value])=>`${key}=${value}`).join(" · ")}</code>:<small>확장 옵션 없음</small>}</div>;}
function statusTone(value){const s=String(value||"").toLowerCase();if(["active","available","completed"].includes(s))return "is-success";if(["error","failed","rejected"].includes(s))return "is-danger";if(["build","creating","attaching","executing","requested"].includes(s))return "is-warning";return "is-muted";}
function statusLabel(value){const map={active:"사용 중",available:"사용 가능",shutoff:"중지",build:"생성 중",error:"오류",requested:"승인 대기",executing:"실행 중",completed:"완료",rejected:"반려",failed:"실패"};return map[String(value||"").toLowerCase()]||value||"-";}
function operationLabel(value){const method=String(value||"").toUpperCase();if(method.includes("/INSTANCES")&&method.startsWith("POST"))return "인스턴스 생성";if(method.includes("/INSTANCES")&&method.startsWith("DELETE"))return "인스턴스 삭제";if(method.includes("/VOLUMES")&&method.startsWith("POST"))return "볼륨 작업";if(method.includes("/VOLUMES")&&method.startsWith("DELETE"))return "볼륨 삭제";if(method.includes("/NETWORKS")&&method.startsWith("POST"))return "네트워크 작업";if(method.includes("/NETWORKS")&&method.startsWith("DELETE"))return "네트워크 삭제";if(method.includes("SECURITY-GROUP"))return "보안그룹 작업";if(method.includes("/DOMAINS"))return "공개 연결 작업";if(method.includes("EXTERNAL-SSH"))return "SSH 포워딩 작업";return value||"OpenStack 작업";}
function addresses(server){return Object.values(server.addresses||{}).flat().map((item)=>item?.addr).filter(Boolean).join(", ")||"-";}
function Field({label,children}){return <label className="mini-horizon-field"><span>{label}</span>{children}</label>;}
function Toolbar({title,onCreate,onRefresh,createLabel="생성"}){return <div className="mini-horizon-toolbar"><div><h3>{title}</h3></div><div>{onRefresh?<button className="mini-btn" onClick={onRefresh} type="button">새로고침</button>:null}{onCreate?<button className="primary-mini-btn" onClick={onCreate} type="button">{createLabel}</button>:null}</div></div>}
function Empty(){return <div className="mini-horizon-empty">표시할 자원이 없습니다.</div>}
function InstanceCreationProgress({name,count=1,completed=0}){const steps=["요청","서버","네트워크","접속정보"];const [step,setStep]=useState(0);useEffect(()=>{const timer=window.setInterval(()=>setStep((value)=>(value+1)%steps.length),1400);return()=>window.clearInterval(timer);},[]);return <div className="loading-card session-loading-card" role="status" aria-live="polite"><div className="session-loading-signal" aria-hidden="true"><span/><span/><span/></div><div className="session-loading-terminal"><div className="session-loading-head"><span className="session-loading-emote" aria-hidden="true">VM</span><span>인스턴스 생성 중</span><i aria-hidden="true">{completed}/{count}</i></div><div className="session-loading-copy"><span className="session-loading-prefix" aria-hidden="true">&gt;</span><span>{name}{count>1?` 외 ${count-1}대`:""} 인스턴스를 생성하고 있습니다. 잠시만 기다려 주세요.</span><span className="session-loading-cursor" aria-hidden="true">_</span></div><div className="session-loading-rail" aria-hidden="true"><span/></div><div className="session-loading-steps" aria-label="인스턴스 생성 단계">{steps.map((label,index)=><span className={index===step?"is-active":""} key={label}>{label}</span>)}</div></div></div>}
function SecurityRuleList({rules=[],mutable=false,onDelete}){return <div className="mini-horizon-rule-list"><div className="mini-horizon-rule-row is-head"><span>방향</span><span>프로토콜</span><span>포트</span><span>원격 대상</span><span>작업</span></div>{rules.length?rules.map((item)=><div className="mini-horizon-rule-row" key={item.id}><span>{item.direction==="ingress"?"수신":"송신"}</span><code>{item.protocol||"전체"}</code><span>{item.port_range_min?(item.port_range_min+(item.port_range_max&&item.port_range_max!==item.port_range_min?"–"+item.port_range_max:"")):"전체 포트"}</span><span>{item.remote_ip_prefix||item.remote_group_id||"전체"}</span>{mutable?<button className="mini-btn danger-mini-btn" onClick={()=>onDelete?.(item)} type="button">삭제</button>:<span className="hint">보호됨</span>}</div>):<div className="mini-horizon-empty">등록된 규칙이 없습니다.</div>}</div>}
function InstanceCredentials({credentials,ssh}){const [revealed,setRevealed]=useState(false);if(!credentials?.username||!credentials?.password)return null;const text="사용자명: "+credentials.username+"\n비밀번호: "+credentials.password+(ssh?.enabled?"\nSSH: "+ssh.command:"");return <div className="mini-horizon-instance-credentials"><span>최초 접속정보</span><code>{credentials.username}</code><code aria-label={revealed?"표시된 비밀번호":"숨겨진 비밀번호"}>{revealed?credentials.password:"••••••••••••"}</code><button className="mini-btn" aria-pressed={revealed} onClick={()=>setRevealed((value)=>!value)} type="button">{revealed?"비밀번호 숨기기":"비밀번호 표시"}</button>{ssh?.enabled?<code>{ssh.command}</code>:<span className="hint">SSH 포워딩 준비 중</span>}<button className="mini-btn" onClick={async()=>{try{await navigator.clipboard.writeText(text);}catch{window.prompt("접속정보를 복사하세요.",text);}}} type="button">전체 복사</button><small>재접속을 위해 안전한 곳에 보관해 주세요.</small></div>}
function InstanceSecurityGroups({server,groups,busy,onAttach,onDetach}){const attached=names((server.security_groups||[]).map((item)=>typeof item==="string"?item:item?.name));const available=(groups||[]).filter((group)=>group?.name&&!attached.includes(group.name));return <div className="mini-horizon-instance-security"><span>보안그룹</span><div>{attached.length?attached.map((name)=><span className="mini-horizon-security-chip" key={name}>{name}<button aria-label={name+" 보안그룹 해제"} disabled={busy||name.toLowerCase()==="example.com"} onClick={()=>onDetach?.(name)} title={name.toLowerCase()==="example.com"?"기본 접속용 보안그룹은 해제할 수 없습니다.":"보안그룹 해제"} type="button">×</button></span>):<span className="hint">연결된 보안그룹 없음</span>}{available.length?<select aria-label={`${server.name||server.id} 인스턴스에 연결할 보안그룹`} defaultValue="" disabled={busy} onChange={(event)=>{const name=event.target.value;if(name)onAttach?.(name);event.target.value="";}}><option value="">보안그룹 연결</option>{available.map((group)=><option key={group.id||group.name} value={group.name}>{group.name}</option>)}</select>:null}</div></div>}
function InstanceDomains({serverId,domains=[],busy,baseDomain="apps.example.com",onCreate,onDelete}){
  const [draft,setDraft]=useState({mode:"domain",subdomain:"",protocol:"http",port:"80",targetPort:"8080"});
  const domainEntries=domains.filter((entry)=>entry.mode!=="tcp");
  const tcpEntries=domains.filter((entry)=>entry.mode==="tcp");
  return <div className="mini-horizon-instance-domains"><span>공개 도메인</span><small>도메인 및 TCP 포워딩</small>
    {domainEntries.length?<div>{domainEntries.map((entry)=><span className="mini-horizon-security-chip" key={entry.subdomain}><a href={entry.url||entry.protocol+"://"+entry.fqdn} rel="noreferrer" target="_blank">{entry.fqdn}</a><button aria-label={entry.fqdn+" 도메인 해제"} disabled={busy} onClick={()=>onDelete?.(entry.subdomain)} type="button">×</button></span>)}</div>:<span className="hint">연결된 도메인 없음</span>}
    {tcpEntries.length?<div>{tcpEntries.map((entry)=><span className="mini-horizon-security-chip" key={entry.externalPort}><code>{entry.host}:{entry.externalPort} → {entry.targetPort}</code><button aria-label={entry.externalPort+" TCP 포워딩 해제"} disabled={busy} onClick={()=>onDelete?.(`tcp-${entry.externalPort}`)} type="button">×</button></span>)}</div>:null}
    <form className="mini-horizon-inline-form" onSubmit={(event)=>{event.preventDefault();onCreate?.(draft.mode==="tcp"?{mode:"tcp",targetPort:Number(draft.targetPort)}:draft);}}>
      <select aria-label="외부 연결 종류" value={draft.mode} onChange={(event)=>setDraft({...draft,mode:event.target.value})}><option value="domain">도메인</option><option value="tcp">TCP 포워딩</option></select>
      {draft.mode==="tcp"?<input aria-label="내부 TCP 포트" min="1" max="65535" required type="number" value={draft.targetPort} onChange={(event)=>setDraft({...draft,targetPort:event.target.value})}/>:<><input aria-label="서브도메인" placeholder="서브도메인(자동 가능)" value={draft.subdomain} onChange={(event)=>setDraft({...draft,subdomain:event.target.value.toLowerCase()})}/><span>.{baseDomain}</span><select aria-label="프로토콜" value={draft.protocol} onChange={(event)=>setDraft({...draft,protocol:event.target.value})}><option value="http">HTTP</option><option value="https">HTTPS</option></select><input aria-label="내부 서비스 포트" min="1" max="65535" required type="number" value={draft.port} onChange={(event)=>setDraft({...draft,port:event.target.value})}/></>}
      <button className="mini-btn" disabled={busy||!serverId} type="submit">{draft.mode==="tcp"?"TCP 연결":"도메인 연결"}</button>
    </form>
  </div>;
}
function QuotaCard({label,metric}){const used=Number(metric?.used||0),limit=Number(metric?.limit||0),percent=limit>0?Math.min(100,Math.round(used/limit*100)):0;return <div className="mini-horizon-quota"><span>{label}</span><strong>{used} / {limit<0?"무제한":limit||"-"}</strong><div><i style={{width:percent+"%"}} /></div></div>}

function LoadBalancerPanel({snapshot,busy,act,refresh}){
  const [form,setForm]=useState("");
  const [loadBalancer,setLoadBalancer]=useState({name:"",vipSubnetId:""});
  const [listener,setListener]=useState({loadBalancerId:"",name:"",protocol:"TCP",protocolPort:"80"});
  const [pool,setPool]=useState({listenerId:"",name:"",protocol:"TCP",algorithm:"ROUND_ROBIN"});
  const [member,setMember]=useState({poolId:"",name:"",address:"",protocolPort:"80",subnetId:""});
  const [monitor,setMonitor]=useState({poolId:"",type:"TCP",delay:"5",timeout:"3",maxRetries:"3",urlPath:"/",expectedCodes:"200"});
  const internalSubnets=(snapshot.subnets||[]).filter((subnet)=>snapshot.networks.some((network)=>network.id===subnet.network_id&&!network["router:external"]));
  const submit=(event,path,body)=>{event.preventDefault();act("POST",path,body,"");};
  return <div className="mini-horizon-content"><Toolbar title="로드밸런서" onRefresh={refresh} onCreate={()=>setForm(form?"":"loadBalancer")} createLabel={form?"입력 닫기":"구성 추가"}/>
    {form?<div className="mini-horizon-dual-form">
      <form className="mini-horizon-form" onSubmit={(e)=>submit(e,"/api/cloud-console/load-balancers",loadBalancer)}><h4>로드밸런서</h4><Field label="이름"><input required value={loadBalancer.name} onChange={(e)=>setLoadBalancer({...loadBalancer,name:e.target.value})}/></Field><Field label="VIP 서브넷"><select required value={loadBalancer.vipSubnetId} onChange={(e)=>setLoadBalancer({...loadBalancer,vipSubnetId:e.target.value})}><option value="">선택</option>{internalSubnets.map((v)=><option key={v.id} value={v.id}>{v.name} · {v.cidr}</option>)}</select></Field><button className="primary-btn" disabled={busy}>생성</button></form>
      <form className="mini-horizon-form" onSubmit={(e)=>submit(e,"/api/cloud-console/load-balancer-listeners",listener)}><h4>리스너</h4><Field label="로드밸런서"><select required value={listener.loadBalancerId} onChange={(e)=>setListener({...listener,loadBalancerId:e.target.value})}><option value="">선택</option>{snapshot.loadBalancers.map((v)=><option key={v.id} value={v.id}>{v.name||v.id}</option>)}</select></Field><Field label="이름"><input required value={listener.name} onChange={(e)=>setListener({...listener,name:e.target.value})}/></Field><Field label="프로토콜"><select value={listener.protocol} onChange={(e)=>setListener({...listener,protocol:e.target.value})}>{["TCP","HTTP","HTTPS","UDP"].map((v)=><option key={v}>{v}</option>)}</select></Field><Field label="포트"><input min="1" max="65535" type="number" required value={listener.protocolPort} onChange={(e)=>setListener({...listener,protocolPort:e.target.value})}/></Field><button className="primary-btn" disabled={busy}>생성</button></form>
      <form className="mini-horizon-form" onSubmit={(e)=>submit(e,"/api/cloud-console/load-balancer-pools",pool)}><h4>풀</h4><Field label="리스너"><select required value={pool.listenerId} onChange={(e)=>setPool({...pool,listenerId:e.target.value})}><option value="">선택</option>{snapshot.loadBalancerListeners.map((v)=><option key={v.id} value={v.id}>{v.name||v.id}</option>)}</select></Field><Field label="이름"><input required value={pool.name} onChange={(e)=>setPool({...pool,name:e.target.value})}/></Field><Field label="프로토콜"><select value={pool.protocol} onChange={(e)=>setPool({...pool,protocol:e.target.value})}>{["TCP","HTTP","HTTPS","UDP"].map((v)=><option key={v}>{v}</option>)}</select></Field><Field label="분산 방식"><select value={pool.algorithm} onChange={(e)=>setPool({...pool,algorithm:e.target.value})}><option value="ROUND_ROBIN">Round Robin</option><option value="LEAST_CONNECTIONS">Least Connections</option><option value="SOURCE_IP">Source IP</option></select></Field><button className="primary-btn" disabled={busy}>생성</button></form>
      <form className="mini-horizon-form" onSubmit={(e)=>submit(e,"/api/cloud-console/load-balancer-pools/"+member.poolId+"/members",member)}><h4>멤버</h4><Field label="풀"><select required value={member.poolId} onChange={(e)=>setMember({...member,poolId:e.target.value})}><option value="">선택</option>{snapshot.loadBalancerPools.map((v)=><option key={v.id} value={v.id}>{v.name||v.id}</option>)}</select></Field><Field label="이름"><input value={member.name} onChange={(e)=>setMember({...member,name:e.target.value})}/></Field><Field label="VM 내부 IP"><select required value={member.address} onChange={(e)=>{const port=snapshot.ports.find((p)=>(p.fixed_ips||[]).some((ip)=>ip.ip_address===e.target.value));const fixed=port?.fixed_ips?.find((ip)=>ip.ip_address===e.target.value);setMember({...member,address:e.target.value,subnetId:fixed?.subnet_id||""});}}><option value="">선택</option>{snapshot.ports.filter((p)=>p.device_owner?.startsWith("compute")).flatMap((p)=>(p.fixed_ips||[]).map((ip)=><option key={p.id+ip.ip_address} value={ip.ip_address}>{snapshot.instances.find((v)=>v.id===p.device_id)?.name||p.name||"VM"} · {ip.ip_address}</option>))}</select></Field><Field label="서비스 포트"><input min="1" max="65535" type="number" required value={member.protocolPort} onChange={(e)=>setMember({...member,protocolPort:e.target.value})}/></Field><button className="primary-btn" disabled={busy}>추가</button></form>
      <form className="mini-horizon-form" onSubmit={(e)=>submit(e,"/api/cloud-console/load-balancer-health-monitors",monitor)}><h4>상태 검사</h4><Field label="풀"><select required value={monitor.poolId} onChange={(e)=>setMonitor({...monitor,poolId:e.target.value})}><option value="">선택</option>{snapshot.loadBalancerPools.map((v)=><option key={v.id} value={v.id}>{v.name||v.id}</option>)}</select></Field><Field label="방식"><select value={monitor.type} onChange={(e)=>setMonitor({...monitor,type:e.target.value})}>{["TCP","HTTP","HTTPS","PING"].map((v)=><option key={v}>{v}</option>)}</select></Field><Field label="주기 / 제한(초)"><div><input min="1" type="number" value={monitor.delay} onChange={(e)=>setMonitor({...monitor,delay:e.target.value})}/><input min="1" type="number" value={monitor.timeout} onChange={(e)=>setMonitor({...monitor,timeout:e.target.value})}/></div></Field><Field label="재시도"><input min="1" max="10" type="number" value={monitor.maxRetries} onChange={(e)=>setMonitor({...monitor,maxRetries:e.target.value})}/></Field>{["HTTP","HTTPS"].includes(monitor.type)?<><Field label="경로"><input value={monitor.urlPath} onChange={(e)=>setMonitor({...monitor,urlPath:e.target.value})}/></Field><Field label="정상 코드"><input value={monitor.expectedCodes} onChange={(e)=>setMonitor({...monitor,expectedCodes:e.target.value})}/></Field></>:null}<button className="primary-btn" disabled={busy}>생성</button></form>
    </div>:null}
    {snapshot.loadBalancers.length?<div className="mini-horizon-table">{snapshot.loadBalancers.map((lb)=>{const listeners=snapshot.loadBalancerListeners.filter((v)=>(v.loadbalancers||[]).some((link)=>link.id===lb.id));return <article key={lb.id}><div><strong>{lb.name||lb.id}</strong><small>{lb.vip_address||"VIP 준비 중"} · {lb.id}</small></div><span className={"status-chip "+statusTone(lb.provisioning_status)}>{statusLabel(lb.provisioning_status)} / {statusLabel(lb.operating_status)}</span>{listeners.map((entry)=>{const pools=snapshot.loadBalancerPools.filter((v)=>(v.listeners||[]).some((link)=>link.id===entry.id));return <div className="mini-horizon-resource-nested" key={entry.id}><strong>{entry.name||entry.id} · {entry.protocol}:{entry.protocol_port}</strong>{pools.map((item)=><p key={item.id}>{item.name||item.id} · {item.lb_algorithm} · 멤버 {snapshot.loadBalancerMembers.filter((v)=>v.pool_id===item.id).length}</p>)}</div>})}<div><button className="mini-btn danger-mini-btn" disabled={busy} onClick={()=>act("DELETE","/api/cloud-console/load-balancers/"+lb.id,{},"로드밸런서와 하위 구성을 삭제합니다.")}>전체 삭제</button></div></article>})}</div>:<Empty/>}
  </div>;
}

function OpenstackServicesPanel({snapshot,busy,act,refresh}){
  const [alarm,setAlarm]=useState({name:"cpu-warning",resourceId:"",metric:"cpu_util",threshold:"80",comparisonOperator:"gt",period:"300"});
  const [reservation,setReservation]=useState({name:"class-reservation",startDate:"",endDate:"",amount:"1",flavor:""});
  const [share,setShare]=useState({name:"shared-data",sizeGb:"10",shareType:"",shareProtocol:"NFS"});
  const submit=(event,path,body)=>{event.preventDefault();act("POST",path,body,"");};
  return <div className="mini-horizon-content"><Toolbar title="공유 스토리지·예약·알림" onRefresh={refresh}/><div className="mini-horizon-dual-form">
    <form className="mini-horizon-form" onSubmit={(event)=>submit(event,"/api/cloud-console/shares",share)}><h4>Manila 공유 스토리지</h4>{snapshot.shareAvailable?<><Field label="이름"><input required value={share.name} onChange={(event)=>setShare({...share,name:event.target.value})}/></Field><Field label="크기(GB)"><input min="1" required type="number" value={share.sizeGb} onChange={(event)=>setShare({...share,sizeGb:event.target.value})}/></Field><Field label="Share Type"><select value={share.shareType} onChange={(event)=>setShare({...share,shareType:event.target.value})}><option value="">기본값</option>{snapshot.shareTypes.map((item)=><option key={item.id||item.name} value={item.name}>{item.name}</option>)}</select></Field><button className="primary-btn" disabled={busy}>공유 생성</button></>:<p className="hint">Manila sharev2 서비스가 설치되지 않았거나 프로젝트에서 사용할 수 없습니다.</p>}</form>
    <form className="mini-horizon-form" onSubmit={(event)=>submit(event,"/api/cloud-console/reservations",reservation)}><h4>Blazar 자원 예약</h4>{snapshot.reservationAvailable?<><Field label="이름"><input required value={reservation.name} onChange={(event)=>setReservation({...reservation,name:event.target.value})}/></Field><Field label="시작"><input required type="datetime-local" value={reservation.startDate} onChange={(event)=>setReservation({...reservation,startDate:event.target.value})}/></Field><Field label="종료"><input required type="datetime-local" value={reservation.endDate} onChange={(event)=>setReservation({...reservation,endDate:event.target.value})}/></Field><Field label="수량"><input min="1" required type="number" value={reservation.amount} onChange={(event)=>setReservation({...reservation,amount:event.target.value})}/></Field><button className="primary-btn" disabled={busy}>예약 생성</button></>:<p className="hint">Blazar reservation 서비스가 설치되지 않았거나 프로젝트에서 사용할 수 없습니다.</p>}</form>
    <form className="mini-horizon-form" onSubmit={(event)=>submit(event,"/api/cloud-console/alarms",alarm)}><h4>Aodh 임계치 알림</h4>{snapshot.alarmAvailable?<><Field label="이름"><input required value={alarm.name} onChange={(event)=>setAlarm({...alarm,name:event.target.value})}/></Field><Field label="대상 인스턴스"><select required value={alarm.resourceId} onChange={(event)=>setAlarm({...alarm,resourceId:event.target.value})}><option value="">선택</option>{snapshot.instances.map((item)=><option key={item.id} value={item.id}>{item.name||item.id}</option>)}</select></Field><Field label="지표"><select value={alarm.metric} onChange={(event)=>setAlarm({...alarm,metric:event.target.value})}><option value="cpu_util">CPU 사용률</option><option value="memory.usage">메모리 사용량</option><option value="disk.capacity">디스크 사용량</option></select></Field><Field label="임계값"><input min="1" required type="number" value={alarm.threshold} onChange={(event)=>setAlarm({...alarm,threshold:event.target.value})}/></Field><button className="primary-btn" disabled={busy}>알림 생성</button></>:<p className="hint">Aodh alarming 서비스가 설치되지 않았거나 프로젝트에서 사용할 수 없습니다.</p>}</form>
  </div><div className="mini-horizon-table">{snapshot.shares.map((item)=><article key={item.id}><div><strong>{item.name||item.id}</strong><small>Manila · {item.size}GB · {item.export_locations?.map((entry)=>entry.path).filter(Boolean).join(", ")||"내보내기 준비 중"}</small></div><span className={"status-chip "+statusTone(item.status)}>{statusLabel(item.status)}</span><button className="mini-btn danger-mini-btn" disabled={busy} onClick={()=>act("DELETE","/api/cloud-console/shares/"+item.id,{},"공유 스토리지 데이터를 삭제합니다.")}>삭제</button></article>)}{snapshot.reservations.map((item)=><article key={item.id}><div><strong>{item.name||item.id}</strong><small>Blazar · {item.start_date} ~ {item.end_date}</small></div><span className={"status-chip "+statusTone(item.status)}>{statusLabel(item.status)}</span><button className="mini-btn danger-mini-btn" disabled={busy} onClick={()=>act("DELETE","/api/cloud-console/reservations/"+item.id,{},"예약을 취소합니다.")}>취소</button></article>)}{snapshot.alarms.map((item)=><article key={item.alarm_id||item.id}><div><strong>{item.name||item.alarm_id}</strong><small>Aodh · {item.state||"상태 대기"}</small></div><span className={"status-chip "+statusTone(item.state)}>{item.state||"-"}</span><button className="mini-btn danger-mini-btn" disabled={busy} onClick={()=>act("DELETE","/api/cloud-console/alarms/"+(item.alarm_id||item.id),{},"알림을 삭제합니다.")}>삭제</button></article>)}</div></div>;
}

function DnsPanel({snapshot,busy,act,refresh}){
  const [zone,setZone]=useState({name:"",email:"admin@example.com",ttl:"300"});
  const [record,setRecord]=useState({zoneId:"",name:"",type:"A",value:"",ttl:"300"});
  const zones=snapshot.dnsZones||[];
  const records=snapshot.dnsRecordsets||[];
  const selectedZone=zones.find((item)=>item.id===record.zoneId);
  function createZone(event){event.preventDefault();act("POST","/api/cloud-console/dns/zones",zone,"");}
  function createRecord(event){event.preventDefault();if(!selectedZone)return;act("POST","/api/cloud-console/dns/zones/"+selectedZone.id+"/recordsets",{zoneName:selectedZone.name,name:record.name,type:record.type,records:[record.value],ttl:record.ttl},"");}
  return <div className="mini-horizon-content"><Toolbar title="내부 도메인" onRefresh={refresh}/>
    <div className="mini-horizon-callout"><strong>Designate 내부 DNS</strong><p><code>apps.example.com</code> 아래의 프로젝트 전용 존과 레코드를 관리합니다. net-infra 인스턴스에는 DNS가 자동 배포됩니다.</p></div>
    {!snapshot.dnsAvailable?<div className="mini-horizon-empty">Designate 서비스에 연결할 수 없습니다. 관리자에게 문의해 주세요.</div>:<>
      <div className="mini-horizon-dual-form">
        <form className="mini-horizon-form" onSubmit={createZone}><h4>도메인 존 생성</h4><Field label="존 이름"><div><input required placeholder="team1" value={zone.name} onChange={(e)=>setZone({...zone,name:e.target.value})}/><small className="hint">짧은 이름 입력 시 team1.apps.example.com로 생성됩니다.</small></div></Field><Field label="관리 이메일"><input required type="email" value={zone.email} onChange={(e)=>setZone({...zone,email:e.target.value})}/></Field><Field label="TTL"><input min="60" type="number" value={zone.ttl} onChange={(e)=>setZone({...zone,ttl:e.target.value})}/></Field><button className="primary-btn" disabled={busy}>존 생성</button></form>
        <form className="mini-horizon-form" onSubmit={createRecord}><h4>DNS 레코드 생성</h4><Field label="존"><select required value={record.zoneId} onChange={(e)=>setRecord({...record,zoneId:e.target.value})}><option value="">선택</option>{zones.map((item)=><option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="호스트 이름"><input required placeholder="web" value={record.name} onChange={(e)=>setRecord({...record,name:e.target.value})}/></Field><Field label="형식"><select value={record.type} onChange={(e)=>setRecord({...record,type:e.target.value})}>{["A","AAAA","CNAME","TXT"].map((item)=><option key={item}>{item}</option>)}</select></Field><Field label="값"><input required placeholder={record.type==="A"?"192.0.2.10":record.type==="CNAME"?"target.example.com":"레코드 값"} value={record.value} onChange={(e)=>setRecord({...record,value:e.target.value})}/></Field><Field label="TTL"><input min="60" type="number" value={record.ttl} onChange={(e)=>setRecord({...record,ttl:e.target.value})}/></Field><button className="primary-btn" disabled={busy||!zones.length}>레코드 생성</button></form>
      </div>
      {zones.length?<div className="mini-horizon-table">{zones.map((zoneItem)=>{const zoneRecords=records.filter((item)=>item.zone_id===zoneItem.id);return <article key={zoneItem.id}><div><strong>{zoneItem.name}</strong><small>{zoneItem.id}</small></div><span className={"status-chip "+statusTone(zoneItem.status)}>{statusLabel(zoneItem.status)}</span><p>TTL {zoneItem.ttl||300}초 · 레코드 {zoneRecords.filter((item)=>!["SOA","NS"].includes(item.type)).length}개</p><div className="mini-horizon-rule-list">{zoneRecords.map((item)=><div className="mini-horizon-rule-row" key={item.id}><span>{item.name}</span><code>{item.type}</code><span>{(item.records||[]).join(", ")}</span><span>{item.ttl||zoneItem.ttl||300}s</span>{!["SOA","NS"].includes(item.type)?<button className="mini-btn danger-mini-btn" disabled={busy} onClick={()=>act("DELETE","/api/cloud-console/dns/zones/"+zoneItem.id+"/recordsets/"+item.id,{},"DNS 레코드를 삭제합니다.")} type="button">삭제</button>:<span className="hint">기본</span>}</div>)}</div><div><button className="mini-btn danger-mini-btn" disabled={busy} onClick={()=>act("DELETE","/api/cloud-console/dns/zones/"+zoneItem.id,{},"도메인 존과 모든 레코드를 삭제합니다.")} type="button">존 삭제</button></div></article>})}</div>:<Empty/>}
    </>}
  </div>;
}

function terminalSocketUrl(path){const protocol=window.location.protocol==="https:"?"wss:":"ws:";return protocol+"//"+window.location.host+path;}
function CloudXterm({session}){const rootRef=useRef(null);useEffect(()=>{if(!session?.wsPath||!rootRef.current)return undefined;const terminal=new Terminal({cursorBlink:true,fontSize:14,theme:{background:"#07111f",foreground:"#e5edf8"}});const fit=new FitAddon();terminal.loadAddon(fit);terminal.open(rootRef.current);fit.fit();terminal.writeln("xterm SSH 세션을 연결합니다.");const socket=new WebSocket(terminalSocketUrl(session.wsPath));socket.addEventListener("open",()=>{fit.fit();socket.send(JSON.stringify({type:"resize",cols:terminal.cols,rows:terminal.rows}));terminal.writeln("대상: "+session.targetLabel);});socket.addEventListener("message",(event)=>{try{const payload=JSON.parse(event.data);if(payload.type==="data"||payload.type==="output")terminal.write(payload.data||"");else if(payload.type==="status")terminal.writeln("\r\n[안내] "+payload.message);else if(payload.type==="error")terminal.writeln("\r\n[오류] "+payload.message);else if(payload.type==="exit")terminal.writeln("\r\n[세션 종료]");}catch{terminal.write(String(event.data||""));}});socket.addEventListener("close",()=>terminal.writeln("\r\n[연결 종료]"));const input=terminal.onData((data)=>{if(socket.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:"input",data}));});const resize=terminal.onResize(({cols,rows})=>{if(socket.readyState===WebSocket.OPEN)socket.send(JSON.stringify({type:"resize",cols,rows}));});const observer=new ResizeObserver(()=>{try{fit.fit();}catch{}});observer.observe(rootRef.current);return()=>{observer.disconnect();input.dispose();resize.dispose();socket.close();terminal.dispose();};},[session?.wsPath]);return <div className="terminal-root is-embedded" ref={rootRef}/>;}

export default function TerminalCloudView(props){
  const projects=useMemo(()=>names((props.selfServiceProjectRequests||[]).filter((request)=>request.status==="approved"&&Number(request.userId)===Number(props.session?.id)).map((request)=>request.projectName||request.requestedProjectName)),[props.session?.id,props.selfServiceProjectRequests]);
  const [project,setProject]=useCommunityUiState("cloud:project",projects[0]||"");
  const [tab,setTab]=useCommunityUiState(`cloud:${project}:tab`,"overview");
  const [listFilters,setListFilters]=useCommunityUiState(`cloud:${project}:filters`,{query:"",status:"all",sort:"name"});
  useEffect(()=>{const next=props.terminalCloudIntent?.tab;if(TABS.some(([key])=>key===next)){setTab(next);setPanel("");}},[props.terminalCloudIntent?.nonce]);
  const [panel,setPanel]=useState("");
  const [busy,setBusy]=useState(false);
  const [creatingInstance,setCreatingInstance]=useState(null);
  const [instanceCreateResult,setInstanceCreateResult]=useState(null);
  const [accessPanel,setAccessPanel]=useState(null);
  const [vncUrl,setVncUrl]=useState("");
  const [sshConnection,setSshConnection]=useState(null);
  const [sshCredentials,setSshCredentials]=useState({username:"",password:""});
  const [cloudTerminalSession,setCloudTerminalSession]=useState(null);
  const [instance,setInstance]=useState({name:"",count:"1",imageRef:"",flavorRef:"",networkId:"",bootVolumeSizeGb:"",bootSource:"image",securityGroupNames:["example.com"]});
  const [volume,setVolume]=useState({name:"",sizeGb:"10",description:""});
  const [network,setNetwork]=useState({name:""});
  const [subnet,setSubnet]=useState({networkId:"",name:"",cidr:"192.168.10.0/24"});
  const [router,setRouter]=useState({name:"",externalNetworkId:""});
  const [routerLink,setRouterLink]=useState({routerId:"",subnetId:""});
  const [floating,setFloating]=useState({floatingNetworkId:"",portId:""});
  const [security,setSecurity]=useState({name:"",description:""});
  const quotaProfiles=props.platformStatus?.selfServiceVmProjectQuotaProfiles||[];
  const quotaMaximum=quotaProfiles.find((profile)=>profile.id==="performance")?.quota||quotaProfiles[0]?.quota||{};
  const [projectSetup,setProjectSetup]=useState({networkName:"private",subnetCidr:"192.168.10.0/24",quotaProfileId:"basic",requestedQuota:{instances:1,cores:1,ram:1024,volumes:1,gigabytes:10}});
  const [rule,setRule]=useState({securityGroupId:"",direction:"ingress",protocol:"tcp",portMin:"22",portMax:"22",remoteIpPrefix:"0.0.0.0/0"});
  const [localActionError,setLocalActionError]=useState("");
  const snapshot=props.cloudConsoleSnapshot?.projectName===project?props.cloudConsoleSnapshot:EMPTY;
  const visibleInstances=filterCommunityInstances(snapshot.instances,listFilters);
  const floatingIpEnabled=Boolean(props.platformStatus?.selfServiceVmFloatingIpEnabled);
  const visibleTabs=TABS.filter(([key])=>(key!=="floatingIps"||floatingIpEnabled)&&(key!=="loadBalancers"||snapshot.loadBalancerAvailable));
  const actions=(props.cloudConsoleActions||[]).filter((a)=>!project||a.projectName===project);
  function creationActionFor(serverId){return actions.find((item)=>(item.operation==="POST /api/cloud-console/instances"||item.operation?.endsWith("/complete-iso-install"))&&item.status==="completed"&&String(item.result?.id||item.result?.server?.id||"")===String(serverId));}
  function credentialsFor(serverId){return creationActionFor(serverId)?.result?.accessCredentials||null;}
  function domainsFor(serverId){const result=creationActionFor(serverId)?.result||{};const domains=Array.isArray(result.publicDomains)?result.publicDomains:[];const tcp=Array.isArray(result.publicTcpRoutes)?result.publicTcpRoutes.map((route)=>({...route,mode:"tcp",subdomain:`tcp-${route.externalPort}`,host:result.externalSshHost||props.platformStatus?.sshPublicHost||"ssh.example.com"})):[];return [...domains,...tcp];}
  function sshAccessFor(serverId){const action=creationActionFor(serverId);const enabled=Boolean(action?.result?.externalSshEnabled&&action?.result?.externalSshPort);const host=action?.result?.externalSshHost||props.platformStatus?.sshPublicHost||"ssh.example.com";const port=Number(action?.result?.externalSshPort||0);const username=action?.result?.accessCredentials?.username||"<사용자명>";return {enabled,host,port,command:enabled?"ssh "+username+"@"+host+" -p "+port:""};}
  function selectedSshAccess(){if(sshConnection?.port){const host=sshConnection.host||props.platformStatus?.sshPublicHost||"ssh.example.com";const port=Number(sshConnection.port);return {enabled:true,host,port,command:sshConnection.command||"ssh <사용자명>@"+host+" -p "+port};}return accessPanel?sshAccessFor(accessPanel.serverId):{enabled:false,host:"",port:0,command:""};}
  const pendingProject=(props.selfServiceProjectRequests||[]).find((request)=>request.status==="requested"&&Number(request.userId)===Number(props.session?.id));
  const [uploadedIso,setUploadedIso]=useState(null);
  const normalImages=names([...(props.platformStatus?.selfServiceVmAllowedImages||[]),...(props.platformStatus?.pocAllowedImages||[])]);
  const isoImages=[...(snapshot.isoImages||[]),...(uploadedIso&&!(snapshot.isoImages||[]).some((row)=>row.id===uploadedIso.id)?[uploadedIso]:[])];
  const images=instance.bootSource==="iso"?names(isoImages.filter((row)=>row.hw_firmware_type==="uefi"&&(String(row.terminal_lab_user_id)===String(props.session?.id)||normalImages.includes(row.name)||normalImages.includes(row.id))).map((row)=>row.id)):normalImages;
  async function isoUploaded(image){setUploadedIso(image);setInstance((current)=>({...current,imageRef:image.id}));try{await props.loadCloudConsoleSnapshot?.(project);}catch{/* The uploaded ISO remains selectable while refresh is retried. */}}

  const dedicatedAiFlavors=new Set((props.platformStatus?.aiVmFlavorCatalog||[]).filter((item)=>item?.enabled!==false).map((item)=>String(item?.flavorName||"").trim()).filter(Boolean));
  const flavors=names(props.platformStatus?.selfServiceVmAllowedFlavors||[]).filter((item)=>!dedicatedAiFlavors.has(item));
  const externalNetworks=snapshot.networks.filter((n)=>n["router:external"]);
  const externalNetworkName=String(props.platformStatus?.selfServiceVmProjectExternalNetworkName||"net-external").trim().toLowerCase();
  const instanceNetworks=snapshot.networks.filter((n)=>!n["router:external"] && String(n.name||"").trim().toLowerCase()!==externalNetworkName).sort((left,right)=>Number(String(right.name||"").toLowerCase()==="net-infra")-Number(String(left.name||"").toLowerCase()==="net-infra"));
  useEffect(()=>{if(!projects.includes(project))setProject(projects[0]||"");},[projects.join("|")]);
  useEffect(()=>{if(!project)return;props.loadCloudConsoleSnapshot?.(project).catch(()=>{});props.loadCloudConsoleActions?.().catch(()=>{});const timer=setInterval(()=>props.loadCloudConsoleSnapshot?.(project).catch(()=>{}),30000);return()=>clearInterval(timer);},[project]);
  useEffect(()=>{if(project)return;props.loadCloudConsoleProject?.().catch(()=>{});const timer=setInterval(()=>props.loadCloudConsoleProject?.().catch(()=>{}),15000);return()=>clearInterval(timer);},[project]);
  useEffect(()=>{setInstance((v)=>({...v,imageRef:images.includes(v.imageRef)?v.imageRef:images[0]||"",flavorRef:flavors.includes(v.flavorRef)?v.flavorRef:flavors[0]||"",networkId:instanceNetworks.some((n)=>n.id===v.networkId)?v.networkId:instanceNetworks.find((n)=>String(n.name||"").trim().toLowerCase()==="net-infra")?.id||instanceNetworks[0]?.id||"",securityGroupNames:snapshot.securityGroups.some((g)=>v.securityGroupNames?.includes(g.name))?v.securityGroupNames:(snapshot.securityGroups.some((g)=>String(g.name||"").toLowerCase()==="example.com")?["example.com"]:[])}));},[images.join("|"),flavors.join("|"),snapshot.refreshedAt]);
  function rememberActionError(error,fallback){setLocalActionError(error?.userMessage||error?.message||fallback);}
  async function act(method,path,body={},warning="이 작업은 비용이 발생할 수 있습니다."){if(busy)return null;if(warning&&!window.confirm(warning+" 계속할까요?"))return null;setBusy(true);setLocalActionError("");try{const result=await props.runCloudConsoleAction?.({method,path,body,projectName:project});setPanel("");return result;}catch(error){rememberActionError(error,"OpenStack 자원 작업을 완료하지 못했습니다.");return null;}finally{setBusy(false);}}
  async function createInstance(event){event.preventDefault();if(busy)return null;const count=Math.max(1,Math.min(10,Number(instance.count||1)||1));const {count:_count,...base}=instance;setBusy(true);setInstanceCreateResult(null);setCreatingInstance({name:base.name||"새 인스턴스",count,completed:0});try{const namesToCreate=Array.from({length:count},(_,index)=>count>1?`${base.name}-${String(index+1).padStart(2,"0")}`:base.name);const settled=await Promise.allSettled(namesToCreate.map(async(name)=>{try{return await props.runCloudConsoleAction?.({method:"POST",path:"/api/cloud-console/instances",body:{...base,name},projectName:project});}finally{setCreatingInstance((current)=>current?{...current,completed:Math.min(current.count,current.completed+1)}:current);}}));const failures=settled.map((result,index)=>result.status==="rejected"?{name:namesToCreate[index],message:result.reason?.userMessage||"인스턴스를 생성하지 못했습니다."}:null).filter(Boolean);setInstanceCreateResult({total:count,success:count-failures.length,failures});return settled;}finally{setBusy(false);setCreatingInstance(null);}}
  async function closeXterm(){const sessionId=cloudTerminalSession?.sessionId;if(sessionId)await props.closeCloudConsoleTerminalSession?.(sessionId);setCloudTerminalSession(null);setSshCredentials((value)=>({...value,password:""}));}
  async function closeAccessPanel(){await closeXterm();setAccessPanel(null);setVncUrl("");setSshConnection(null);}
  function changeAccessMode(mode){if(accessPanel?.mode==="xterm"&&mode!=="xterm")void closeXterm();setAccessPanel((value)=>value?{...value,mode}:value);}
  function selectAccess(server,mode){if(cloudTerminalSession?.sessionId)void props.closeCloudConsoleTerminalSession?.(cloudTerminalSession.sessionId);setAccessPanel({serverId:server.id,name:server.name||server.id,mode});setCloudTerminalSession(null);setSshCredentials(credentialsFor(server.id)||{username:"",password:""});setVncUrl("");setSshConnection(null);}
  async function openConsole(server){selectAccess(server,"vnc");setBusy(true);setLocalActionError("");try{const result=await props.openCloudConsole?.({serverId:server.id,projectName:project});setVncUrl(result?.consoleUrl||"");}catch(error){rememberActionError(error,"VNC 콘솔을 열지 못했습니다.");}finally{setBusy(false);}}
  async function startSshForwarding(){if(!accessPanel)return;setBusy(true);setLocalActionError("");try{const result=await props.runCloudConsoleAction?.({method:"POST",path:"/api/cloud-console/instances/"+accessPanel.serverId+"/external-ssh",body:{},projectName:project});setSshConnection(result?.result||null);}catch(error){rememberActionError(error,"SSH 포워딩을 시작하지 못했습니다.");}finally{setBusy(false);}}
  async function stopSshForwarding(){if(!accessPanel)return;setBusy(true);setLocalActionError("");try{await props.runCloudConsoleAction?.({method:"DELETE",path:"/api/cloud-console/instances/"+accessPanel.serverId+"/external-ssh",body:{},projectName:project});setSshConnection(null);}catch(error){rememberActionError(error,"SSH 포워딩을 중지하지 못했습니다.");}finally{setBusy(false);}}
  async function copySshCommand(){const command=selectedSshAccess().command;if(!command)return;try{await navigator.clipboard.writeText(command);}catch{window.prompt("SSH 접속 명령을 복사하세요.",command);}}
  async function startXterm(event){event.preventDefault();if(!accessPanel)return;setBusy(true);setLocalActionError("");try{const result=await props.createCloudConsoleTerminalSession?.({serverId:accessPanel.serverId,projectName:project,...sshCredentials});setCloudTerminalSession(result||null);setSshCredentials((value)=>({...value,password:""}));}catch(error){rememberActionError(error,"xterm SSH 콘솔을 열지 못했습니다.");}finally{setBusy(false);}}
  function submit(e,method,path,body){e.preventDefault();return act(method,path,body);}
  function manageSecurityGroupRules(group){setRule((value)=>({...value,securityGroupId:group.id}));setPanel("rules");}
  const refresh=()=>props.loadCloudConsoleSnapshot?.(project);
  async function createProject(e){
    e.preventDefault();setBusy(true);setLocalActionError("");
    try{const result=await props.createCloudConsoleProject?.(projectSetup);const name=result?.projectRequest?.projectName||"";if(result?.automaticallyApproved&&name){setProject(name);await props.loadCloudConsoleSnapshot?.(name);}}catch(error){rememberActionError(error,"전용 프로젝트를 생성하지 못했습니다.");}finally{setBusy(false);}
  }
  async function deleteProject(){
    if(!project||busy)return;const confirmation=window.prompt(`프로젝트와 포함된 모든 자원을 삭제합니다. 계속하려면 ${project} 을(를) 입력하세요.`);if(confirmation!==project)return;
    setBusy(true);setLocalActionError("");try{await props.deleteCloudConsoleProject?.({projectName:project,confirmProjectName:confirmation});setProject("");setPanel("");setTab("overview");await props.loadCloudConsoleProject?.();}catch(error){rememberActionError(error,"전용 프로젝트를 삭제하지 못했습니다.");}finally{setBusy(false);}
  }
  const q=snapshot.quota?.metrics||{};
  const updateRequestedQuota=(key,value)=>setProjectSetup((current)=>({...current,requestedQuota:{...current.requestedQuota,[key]:Number(value)}}));
  const customQuotaFields=projectSetup.quotaProfileId==="custom"?<div className="mini-horizon-dual-form">
    <Field label="VM 개수"><input type="number" min="1" max={quotaMaximum.instances} required value={projectSetup.requestedQuota.instances} onChange={(e)=>updateRequestedQuota("instances",e.target.value)}/></Field>
    <Field label="vCPU 개수"><input type="number" min="1" max={quotaMaximum.cores} required value={projectSetup.requestedQuota.cores} onChange={(e)=>updateRequestedQuota("cores",e.target.value)}/></Field>
    <Field label="RAM (GB)"><input type="number" min="1" max={Math.floor((quotaMaximum.ram||1024)/1024)} required value={Math.round(projectSetup.requestedQuota.ram/1024)} onChange={(e)=>updateRequestedQuota("ram",Number(e.target.value)*1024)}/></Field>
    <Field label="볼륨 개수"><input type="number" min="1" max={quotaMaximum.volumes} required value={projectSetup.requestedQuota.volumes} onChange={(e)=>updateRequestedQuota("volumes",e.target.value)}/></Field>
    <Field label="총 디스크 (GB)"><input type="number" min="1" max={quotaMaximum.gigabytes} required value={projectSetup.requestedQuota.gigabytes} onChange={(e)=>updateRequestedQuota("gigabytes",e.target.value)}/></Field>
  </div>:null;
  return <section aria-busy={busy} className="mini-horizon-shell">
    <header className="mini-horizon-header"><div><span>오픈스택 프로젝트</span><h2>클라우드 콘솔</h2><p>실제 OpenStack 자원을 생성하고 관리합니다. 모든 사용분은 비용에 반영됩니다.</p></div><div><label>프로젝트<select value={project} disabled={busy} onChange={(e)=>{setUploadedIso(null);setProject(e.target.value);}}>{projects.length ? projects.map((p)=><option key={p}>{p}</option>) : <option value="" disabled>프로젝트 비어 있음</option>}</select></label>{project?<details><summary>프로젝트 관리</summary><button className="mini-btn danger-mini-btn" disabled={busy} onClick={deleteProject} type="button">프로젝트 삭제</button></details>:<button className="primary-mini-btn" onClick={()=>document.querySelector(".mini-horizon-project-form select")?.focus()} type="button">생성</button>}</div></header>
    {props.cloudConsoleStatus?.message?<div aria-live={props.cloudConsoleStatus.tone==="error"?"assertive":"polite"} className={"mini-horizon-status is-"+(props.cloudConsoleStatus.tone||"info")} role={props.cloudConsoleStatus.tone==="error"?"alert":"status"}>{props.cloudConsoleStatus.message}</div>:null}
    {localActionError&&localActionError!==props.cloudConsoleStatus?.message?<div aria-live="assertive" className="mini-horizon-status is-error" role="alert">{localActionError}</div>:null}
    {instanceCreateResult?<div aria-live="polite" className={`mini-horizon-create-result ${instanceCreateResult.failures.length?"is-warning":"is-success"}`} role="status"><strong>{`인스턴스 생성 결과 · 성공 ${instanceCreateResult.success}/${instanceCreateResult.total}`}</strong>{instanceCreateResult.failures.length?<ul>{instanceCreateResult.failures.map((item)=><li key={item.name}><b>{item.name}</b><span>{item.message}</span></li>)}</ul>:<span>요청한 인스턴스를 모두 생성했습니다.</span>}</div>:null}
    {!project?<div className="mini-horizon-content"><Toolbar title="전용 프로젝트 준비"/><form className="mini-horizon-form mini-horizon-project-form" onSubmit={createProject}><Field label="자원 구성"><select value={projectSetup.quotaProfileId} onChange={(e)=>setProjectSetup({...projectSetup,quotaProfileId:e.target.value})}>{quotaProfiles.map((profile)=><option key={profile.id} value={profile.id}>{profile.label} · VM {profile.quota.instances} · vCPU {profile.quota.cores} · RAM {Math.round(profile.quota.ram/1024)}GB · Disk {profile.quota.gigabytes}GB</option>)}<option value="custom">직접 설정</option></select></Field>{customQuotaFields}<Field label="기본 네트워크"><input required value={projectSetup.networkName} onChange={(e)=>setProjectSetup({...projectSetup,networkName:e.target.value})}/></Field><Field label="서브넷 CIDR"><input required value={projectSetup.subnetCidr} onChange={(e)=>setProjectSetup({...projectSetup,subnetCidr:e.target.value})}/></Field>{pendingProject?<div className="mini-horizon-status is-warning">관리자 승인 대기 중입니다.</div>:null}<button className="primary-btn" disabled={busy||Boolean(pendingProject)}>{busy?"구성 중":pendingProject?"승인 대기":"프로젝트 생성"}</button></form></div>:<>
      <nav aria-label="클라우드 콘솔 자원" className="mini-horizon-tabs" role="tablist">{visibleTabs.map(([key,label,group],index)=><button aria-selected={tab===key} className={`${tab===key?"is-active":""} ${index>0&&visibleTabs[index-1]?.[2]!==group?"is-group-start":""}`.trim()} key={key} onClick={()=>{setTab(key);setPanel("");}} role="tab" type="button">{label}</button>)}</nav>
      {tab==="overview"?<div className="mini-horizon-content"><Toolbar title="프로젝트 개요" onRefresh={refresh}/><div className="mini-horizon-quota-grid"><QuotaCard label="인스턴스" metric={q.instances}/><QuotaCard label="vCPU" metric={q.cores}/><QuotaCard label="RAM(MB)" metric={q.ram}/><QuotaCard label="볼륨" metric={q.volumes}/><QuotaCard label="스토리지(GB)" metric={q.volumeStorage}/><QuotaCard label="네트워크" metric={q.networks}/><QuotaCard label="라우터" metric={q.routers}/>{floatingIpEnabled?<QuotaCard label="유동 IP" metric={q.floatingIps}/>:null}</div><div className="mini-horizon-overview-counts"><div><strong>{snapshot.instances.length}</strong><span>인스턴스</span></div><div><strong>{snapshot.volumes.length}</strong><span>볼륨</span></div><div><strong>{snapshot.networks.length}</strong><span>네트워크</span></div><div><strong>{actions.filter((a)=>a.status==="requested").length}</strong><span>승인 대기</span></div></div>{snapshot.warnings?.length?<div className="mini-horizon-warnings">{snapshot.warnings.map((w,i)=><div key={i}>{w}</div>)}</div>:null}</div>:null}
      {tab==="instances"?<div className="mini-horizon-content"><div className="community-vm-filters"><label>가상머신 검색<input type="search" aria-label="가상머신 검색" value={listFilters.query} onChange={e=>setListFilters(v=>({...v,query:e.target.value}))}/></label><label>상태<select aria-label="가상머신 상태" value={listFilters.status} onChange={e=>setListFilters(v=>({...v,status:e.target.value}))}><option value="all">전체</option><option value="ACTIVE">실행 중</option><option value="SHUTOFF">중지</option><option value="BUILD">생성 중</option><option value="ERROR">오류</option></select></label><label>정렬<select aria-label="가상머신 정렬" value={listFilters.sort} onChange={e=>setListFilters(v=>({...v,sort:e.target.value}))}><option value="name">이름순</option><option value="status">상태순</option></select></label><button type="button" onClick={()=>setListFilters({query:"",status:"all",sort:"name"})}>조건 초기화</button><span role="status">표시 {visibleInstances.length} / 전체 {snapshot.instances.length}대</span></div><CommunityBulkStart key={project} instances={snapshot.instances} visibleInstances={visibleInstances} projectName={project} busy={busy} onBusy={setBusy} onAction={props.runCloudConsoleAction}/><Toolbar title="인스턴스" onRefresh={refresh} onCreate={()=>setPanel(panel==="instance"?"":"instance")} createLabel="인스턴스 생성"/>{creatingInstance?<InstanceCreationProgress name={creatingInstance.name} count={creatingInstance.count} completed={creatingInstance.completed}/>:null}{panel==="instance"?<form className="mini-horizon-form mini-horizon-instance-form" onSubmit={createInstance}><Field label="이름"><input required value={instance.name} onChange={(e)=>setInstance({...instance,name:e.target.value})}/></Field><Field label="부팅 방식"><select value={instance.bootSource} onChange={(event)=>setInstance((current)=>({...current,bootSource:event.target.value,imageRef:"",bootVolumeSizeGb:event.target.value==="iso"?"32":""}))}><option value="image">설치된 이미지로 생성</option><option value="iso">ISO로 OS 설치</option></select></Field>{instance.bootSource==="iso"?<IsoUploadFields projectName={project} canUpload={props.session?.role==="admin"} disabled={busy} onBusy={setBusy} onUploaded={isoUploaded}/>:null}<Field label="이미지"><select required value={instance.imageRef} onChange={(e)=>setInstance({...instance,imageRef:e.target.value})}>{images.length?images.map((image)=><option key={image} value={image}>{instance.bootSource==="iso"?(isoImages.find((row)=>row.id===image)?.name||image):image}</option>):<option value="" disabled>사용 가능한 이미지 없음</option>}</select></Field><Field label="Flavor"><select required value={instance.flavorRef} onChange={(e)=>setInstance({...instance,flavorRef:e.target.value})}>{flavors.map((v)=><option key={v} value={v}>{flavorLabel(v,snapshot,props.platformStatus)}</option>)}</select><FlavorDetails flavor={instance.flavorRef} snapshot={snapshot} platformStatus={props.platformStatus}/></Field><Field label="네트워크"><select required value={instance.networkId} onChange={(e)=>setInstance({...instance,networkId:e.target.value})}>{instanceNetworks.length?instanceNetworks.map((n)=><option key={n.id} value={n.id}>{n.name}</option>):<option value="" disabled>사용 가능한 네트워크 없음</option>}</select></Field><Field label="보안그룹"><select value={instance.securityGroupNames?.[0]||""} onChange={(e)=>setInstance({...instance,securityGroupNames:e.target.value?[e.target.value]:[]})}><option value="">기본 보안그룹</option>{snapshot.securityGroups.map((g)=><option key={g.id} value={g.name}>{g.name}</option>)}</select></Field><Field label="생성 수량"><input max="10" min="1" required type="number" value={instance.count} onChange={(e)=>setInstance({...instance,count:e.target.value})}/></Field><Field label={instance.bootSource==="iso"?"설치 디스크(GB)":"부팅 볼륨(GB, 선택)"}><input min={instance.bootSource==="iso"?"8":"0"} max="2048" required={instance.bootSource==="iso"} type="number" value={instance.bootVolumeSizeGb} onChange={(e)=>setInstance({...instance,bootVolumeSizeGb:e.target.value})}/></Field><button className="primary-btn" disabled={busy}>{creatingInstance?"생성 중...":"생성"}</button></form>:null}{visibleInstances.length?<div className="mini-horizon-table">{visibleInstances.map((s)=><article key={s.id}><div><strong>{s.name}</strong><small>{s.id}</small></div><span className={"status-chip "+statusTone(s.status)}>{statusLabel(s.status)}</span><p>{addresses(s)}</p><details className="community-connect-menu"><summary>접속</summary><div><button type="button" className="mini-btn" disabled={String(s.status).toUpperCase()!=="ACTIVE"||busy} onClick={()=>openConsole(s)}>VNC</button><button type="button" className="mini-btn" disabled={String(s.status).toUpperCase()!=="ACTIVE"||busy} onClick={()=>selectAccess(s,"ssh")}>외부 SSH</button><button type="button" className="mini-btn" disabled={String(s.status).toUpperCase()!=="ACTIVE"||busy} onClick={()=>selectAccess(s,"xterm")}>웹 터미널</button>{String(s.status).toUpperCase()!=="ACTIVE"?<small>실행 중인 VM에서 접속할 수 있습니다.</small>:null}</div></details><details className="community-vm-management"><summary>상세·관리</summary><InstanceCredentials credentials={credentialsFor(s.id)} ssh={sshAccessFor(s.id)}/><IsoInstallStatus server={s} runtimeServerId={snapshot.instances.find((row)=>row.metadata?.terminal_lab_iso_origin_id===s.id)?.id} busy={busy} onComplete={()=>act("POST","/api/cloud-console/instances/"+s.id+"/complete-iso-install",{installationConfirmed:true},"OS 설치와 정상 종료를 확인했나요? 설치 디스크의 스냅샷으로 새 실행 VM을 만들고 원본은 보존합니다.")}/><InstanceSecurityGroups server={s} groups={snapshot.securityGroups} busy={busy} onAttach={(name)=>act("POST","/api/cloud-console/instances/"+s.id+"/security-groups",{securityGroupName:name},"")} onDetach={(name)=>act("DELETE","/api/cloud-console/instances/"+s.id+"/security-groups/"+encodeURIComponent(name),{},"보안그룹 연결을 해제합니다.")}/><InstanceDomains serverId={s.id} domains={domainsFor(s.id)} busy={busy} baseDomain={props.platformStatus?.labBaseDomain||"apps.example.com"} onCreate={(draft)=>act("POST","/api/cloud-console/instances/"+s.id+"/domains",draft,"")} onDelete={(subdomain)=>act("DELETE","/api/cloud-console/instances/"+s.id+"/domains/"+encodeURIComponent(subdomain),{},"도메인 연결을 해제합니다.")}/>{sshAccessFor(s.id).enabled?<p className="hint"><code>{sshAccessFor(s.id).command}</code></p>:null}<div>{String(s.status).toUpperCase()==="SHUTOFF"?<button className="mini-btn" onClick={()=>act("POST","/api/cloud-console/instances/"+s.id+"/action",{action:"start"},"")}>시작</button>:<button className="mini-btn" onClick={()=>act("POST","/api/cloud-console/instances/"+s.id+"/action",{action:"stop"},"")}>중지</button>}<button className="mini-btn" onClick={()=>act("POST","/api/cloud-console/instances/"+s.id+"/action",{action:"reboot"},"")}>재부팅</button><button className="mini-btn danger-mini-btn" onClick={()=>act("DELETE","/api/cloud-console/instances/"+s.id,{},"인스턴스를 삭제하면 복구할 수 없습니다.")}>삭제</button></div></details></article>)}</div>:<Empty/>}{accessPanel?<section className="mini-horizon-access-panel"><header><div><strong>{accessPanel.name}</strong><small>{accessPanel.serverId}</small></div><button className="mini-btn" onClick={closeAccessPanel} type="button">닫기</button></header><nav><button className={accessPanel.mode==="vnc"?"is-active":""} onClick={()=>{setAccessPanel({...accessPanel,mode:"vnc"});if(!vncUrl)openConsole({id:accessPanel.serverId,name:accessPanel.name});}} type="button">VNC</button><button className={accessPanel.mode==="ssh"?"is-active":""} onClick={()=>changeAccessMode("ssh")} type="button">SSH</button><button className={accessPanel.mode==="xterm"?"is-active":""} onClick={()=>changeAccessMode("xterm")} type="button">xterm</button></nav>{accessPanel.mode==="vnc"?<div className="mini-horizon-console-frame">{vncUrl?<><button className="mini-btn" disabled={busy} onClick={()=>openConsole({id:accessPanel.serverId,name:accessPanel.name})} type="button">VNC 새로고침</button><iframe allow="clipboard-read; clipboard-write" src={vncUrl} title={accessPanel.name+" VNC"}/></>:<p className="hint">VNC 콘솔을 준비하고 있습니다.</p>}</div>:null}{accessPanel.mode==="ssh"?<div className="mini-horizon-access-body">{selectedSshAccess().enabled?<><div className="mini-horizon-endpoint"><strong>{selectedSshAccess().host}:{selectedSshAccess().port}</strong><code>{selectedSshAccess().command}</code></div><button className="mini-btn" onClick={copySshCommand} type="button">접속 명령 복사</button><button className="mini-btn" onClick={stopSshForwarding}>SSH 포워딩 해제</button></>:<button className="primary-btn" disabled={busy} onClick={startSshForwarding}>SSH 포워딩 시작</button>}</div>:null}{accessPanel.mode==="xterm"?<div className="mini-horizon-access-body">{cloudTerminalSession?<><button className="mini-btn danger-mini-btn" onClick={closeXterm} type="button">xterm 연결 종료</button><CloudXterm session={cloudTerminalSession}/></>:<form className="mini-horizon-form" onSubmit={startXterm}><Field label="SSH 사용자명"><input required autoComplete="username" value={sshCredentials.username} onChange={(e)=>setSshCredentials({...sshCredentials,username:e.target.value})}/></Field><Field label="SSH 비밀번호"><input required autoComplete="current-password" type="password" value={sshCredentials.password} onChange={(e)=>setSshCredentials({...sshCredentials,password:e.target.value})}/></Field><button className="primary-btn" disabled={busy}>xterm 연결</button></form>}</div>:null}</section>:null}</div>:null}
      {tab==="volumes"?<div className="mini-horizon-content"><Toolbar title="볼륨" onRefresh={refresh} onCreate={()=>setPanel(panel==="volume"?"":"volume")} createLabel="볼륨 생성"/>{panel==="volume"?<form className="mini-horizon-form" onSubmit={(e)=>submit(e,"POST","/api/cloud-console/volumes",volume)}><Field label="이름"><input required value={volume.name} onChange={(e)=>setVolume({...volume,name:e.target.value})}/></Field><Field label="크기(GB)"><input min="1" type="number" required value={volume.sizeGb} onChange={(e)=>setVolume({...volume,sizeGb:e.target.value})}/></Field><Field label="설명"><input value={volume.description} onChange={(e)=>setVolume({...volume,description:e.target.value})}/></Field><button className="primary-btn" disabled={busy}>생성</button></form>:null}{snapshot.volumes.length?<div className="mini-horizon-table">{snapshot.volumes.map((v)=>{const attachment=v.attachments?.[0];return <article key={v.id}><div><strong>{v.name||v.id}</strong><small>{v.id}</small></div><span className={"status-chip "+statusTone(v.status)}>{statusLabel(v.status)}</span><p>{v.size} GB · {attachment?"연결됨":"미연결"}</p><div>{attachment?<button className="mini-btn" onClick={()=>act("POST","/api/cloud-console/volumes/"+v.id+"/detach",{serverId:attachment.server_id,attachmentId:attachment.attachment_id||v.id})}>분리</button>:<select defaultValue="" onChange={(e)=>{if(e.target.value)act("POST","/api/cloud-console/volumes/"+v.id+"/attach",{serverId:e.target.value});}}><option value="">인스턴스 연결</option>{snapshot.instances.map((s)=><option key={s.id} value={s.id}>{s.name}</option>)}</select>}<button className="mini-btn danger-mini-btn" disabled={Boolean(attachment)} onClick={()=>act("DELETE","/api/cloud-console/volumes/"+v.id,{},"볼륨 데이터가 모두 삭제됩니다.")}>삭제</button></div></article>})}</div>:<Empty/>}</div>:null}
      {tab==="networks"?<div className="mini-horizon-content"><Toolbar title="네트워크·서브넷" onRefresh={refresh} onCreate={()=>setPanel(panel==="network"?"":"network")} createLabel="네트워크 생성"/>{panel==="network"?<div className="mini-horizon-dual-form"><form className="mini-horizon-form" onSubmit={(e)=>submit(e,"POST","/api/cloud-console/networks",network)}><h4>네트워크</h4><Field label="이름"><input required value={network.name} onChange={(e)=>setNetwork({name:e.target.value})}/></Field><button className="primary-btn" disabled={busy}>생성</button></form><form className="mini-horizon-form" onSubmit={(e)=>submit(e,"POST","/api/cloud-console/subnets",subnet)}><h4>서브넷</h4><Field label="네트워크"><select required value={subnet.networkId} onChange={(e)=>setSubnet({...subnet,networkId:e.target.value})}><option value="">선택</option>{snapshot.networks.filter((n)=>!n["router:external"]).map((n)=><option key={n.id} value={n.id}>{n.name}</option>)}</select></Field><Field label="이름"><input required value={subnet.name} onChange={(e)=>setSubnet({...subnet,name:e.target.value})}/></Field><Field label="CIDR"><input required value={subnet.cidr} onChange={(e)=>setSubnet({...subnet,cidr:e.target.value})}/></Field><button className="primary-btn" disabled={busy}>생성</button></form></div>:null}<div className="mini-horizon-table">{snapshot.networks.map((n)=><article key={n.id}><div><strong>{n.name||n.id}</strong><small>{n.id}</small></div><span className="status-chip is-success">{n["router:external"]?"외부":"내부"}</span><p>{snapshot.subnets.filter((s)=>s.network_id===n.id).map((s)=>s.name+" "+s.cidr).join(", ")||"서브넷 없음"}</p><div>{snapshot.subnets.filter((s)=>s.network_id===n.id).map((s)=><button className="mini-btn danger-mini-btn" key={s.id} onClick={()=>act("DELETE","/api/cloud-console/subnets/"+s.id,{},"서브넷을 삭제합니다.")}>{s.name} 삭제</button>)}{!n["router:external"]?<><select defaultValue="" disabled={busy} onChange={(e)=>{if(e.target.value)act("POST","/api/cloud-console/instances/"+e.target.value+"/networks",{networkId:n.id},"");e.target.value="";}}><option value="">실행 중 VM에 연결</option>{snapshot.instances.filter((s)=>String(s.status).toUpperCase()==="ACTIVE"&&!snapshot.ports.some((p)=>p.device_id===s.id&&p.network_id===n.id)).map((s)=><option key={s.id} value={s.id}>{s.name}</option>)}</select>{snapshot.ports.filter((p)=>p.network_id===n.id&&p.device_owner?.startsWith("compute")&&snapshot.instances.some((s)=>s.id===p.device_id)).map((p)=><button className="mini-btn" key={p.id} onClick={()=>act("DELETE","/api/cloud-console/instances/"+p.device_id+"/networks/"+p.id,{},"네트워크 연결을 해제합니다.")}>{snapshot.instances.find((s)=>s.id===p.device_id)?.name||"VM"} 연결 해제</button>)}<button className="mini-btn danger-mini-btn" onClick={()=>act("DELETE","/api/cloud-console/networks/"+n.id,{},"네트워크를 삭제합니다.")}>네트워크 삭제</button></>:null}</div></article>)}</div></div>:null}
      {tab==="routers"?<div className="mini-horizon-content"><Toolbar title="라우터" onRefresh={refresh} onCreate={()=>setPanel(panel==="router"?"":"router")} createLabel="라우터 생성"/>{panel==="router"?<div className="mini-horizon-dual-form"><form className="mini-horizon-form" onSubmit={(e)=>submit(e,"POST","/api/cloud-console/routers",router)}><Field label="이름"><input required value={router.name} onChange={(e)=>setRouter({...router,name:e.target.value})}/></Field><Field label="외부 네트워크"><select value={router.externalNetworkId} onChange={(e)=>setRouter({...router,externalNetworkId:e.target.value})}><option value="">없음</option>{externalNetworks.map((n)=><option key={n.id} value={n.id}>{n.name}</option>)}</select></Field><button className="primary-btn" disabled={busy}>생성</button></form><form className="mini-horizon-form" onSubmit={(e)=>submit(e,"POST","/api/cloud-console/routers/"+routerLink.routerId+"/interfaces",{subnetId:routerLink.subnetId})}><Field label="라우터"><select required value={routerLink.routerId} onChange={(e)=>setRouterLink({...routerLink,routerId:e.target.value})}><option value="">선택</option>{snapshot.routers.map((v)=><option key={v.id} value={v.id}>{v.name}</option>)}</select></Field><Field label="서브넷"><select required value={routerLink.subnetId} onChange={(e)=>setRouterLink({...routerLink,subnetId:e.target.value})}><option value="">선택</option>{snapshot.subnets.map((v)=><option key={v.id} value={v.id}>{v.name}</option>)}</select></Field><button className="primary-btn" disabled={busy}>연결</button></form></div>:null}<div className="mini-horizon-table">{snapshot.routers.map((v)=><article key={v.id}><div><strong>{v.name||v.id}</strong><small>{v.id}</small></div><span className={"status-chip "+statusTone(v.status)}>{statusLabel(v.status)}</span><p>{v.external_gateway_info?.network_id?"외부 게이트웨이 연결":"외부 게이트웨이 없음"}</p><div>{snapshot.ports.filter((p)=>p.device_id===v.id&&String(p.device_owner||"").includes("router_interface")).flatMap((p)=>(p.fixed_ips||[]).map((ip)=>({port:p,subnetId:ip.subnet_id}))).map((link)=><button className="mini-btn" key={link.port.id+link.subnetId} onClick={()=>act("DELETE","/api/cloud-console/routers/"+v.id+"/interfaces/"+link.subnetId,{},"라우터와 서브넷 연결을 해제합니다.")}>인터페이스 해제</button>)}<button className="mini-btn danger-mini-btn" onClick={()=>act("DELETE","/api/cloud-console/routers/"+v.id,{},"라우터 인터페이스를 먼저 해제해야 할 수 있습니다.")}>삭제</button></div></article>)}</div></div>:null}
      {tab==="floatingIps"&&floatingIpEnabled?<div className="mini-horizon-content"><Toolbar title="유동 IP" onRefresh={refresh} onCreate={()=>setPanel(panel==="floating"?"":"floating")} createLabel="IP 할당"/>{panel==="floating"?<form className="mini-horizon-form" onSubmit={(e)=>submit(e,"POST","/api/cloud-console/floating-ips",floating)}><Field label="외부 네트워크"><select required value={floating.floatingNetworkId} onChange={(e)=>setFloating({...floating,floatingNetworkId:e.target.value})}><option value="">선택</option>{externalNetworks.map((n)=><option key={n.id} value={n.id}>{n.name}</option>)}</select></Field><Field label="포트(선택)"><select value={floating.portId} onChange={(e)=>setFloating({...floating,portId:e.target.value})}><option value="">할당만</option>{snapshot.ports.filter((p)=>p.device_owner?.startsWith("compute")).map((p)=><option key={p.id} value={p.id}>{p.name||p.fixed_ips?.[0]?.ip_address||p.id}</option>)}</select></Field><button className="primary-btn" disabled={busy}>할당</button></form>:null}<div className="mini-horizon-table">{snapshot.floatingIps.map((v)=><article key={v.id}><div><strong>{v.floating_ip_address}</strong><small>{v.id}</small></div><span className={"status-chip "+statusTone(v.status)}>{statusLabel(v.status)}</span><p>{v.fixed_ip_address||"미연결"}</p><div>{v.port_id?<button className="mini-btn" onClick={()=>act("POST","/api/cloud-console/floating-ips/"+v.id+"/association",{portId:""},"유동 IP 연결을 해제합니다.")}>연결 해제</button>:<select defaultValue="" onChange={(e)=>{if(e.target.value)act("POST","/api/cloud-console/floating-ips/"+v.id+"/association",{portId:e.target.value},"유동 IP를 포트에 연결합니다.")}}><option value="">포트 연결</option>{snapshot.ports.filter((p)=>p.device_owner?.startsWith("compute")).map((p)=><option key={p.id} value={p.id}>{p.name||p.fixed_ips?.[0]?.ip_address||p.id}</option>)}</select>}<button className="mini-btn danger-mini-btn" onClick={()=>act("DELETE","/api/cloud-console/floating-ips/"+v.id,{},"유동 IP를 반납합니다.")}>반납</button></div></article>)}</div></div>:null}
      {tab==="loadBalancers"?<LoadBalancerPanel snapshot={snapshot} busy={busy} act={act} refresh={refresh}/>:null}
      {tab==="dns"?<DnsPanel snapshot={snapshot} busy={busy} act={act} refresh={refresh}/>:null}
      {tab==="services"?<OpenstackServicesPanel snapshot={snapshot} busy={busy} act={act} refresh={refresh}/>:null}
      {tab==="securityGroups"?<div className="mini-horizon-content"><Toolbar title="보안그룹" onRefresh={refresh} onCreate={()=>setPanel(panel==="security"?"":"security")} createLabel="보안그룹 생성"/>{panel==="security"?<div className="mini-horizon-dual-form"><form className="mini-horizon-form" onSubmit={(e)=>submit(e,"POST","/api/cloud-console/security-groups",security)}><Field label="이름"><input required value={security.name} onChange={(e)=>setSecurity({...security,name:e.target.value})}/></Field><Field label="설명"><input value={security.description} onChange={(e)=>setSecurity({...security,description:e.target.value})}/></Field><button className="primary-btn" disabled={busy}>생성</button></form></div>:null}{panel==="rules"?<div className="mini-horizon-dual-form"><form className="mini-horizon-form" onSubmit={(e)=>submit(e,"POST","/api/cloud-console/security-groups/"+rule.securityGroupId+"/rules",rule)}><Field label="보안그룹"><select required value={rule.securityGroupId} onChange={(e)=>setRule({...rule,securityGroupId:e.target.value})}><option value="">선택</option>{snapshot.securityGroups.filter((g)=>!["default","example.com"].includes(String(g.name||"").toLowerCase())).map((g)=><option key={g.id} value={g.id}>{g.name}</option>)}</select></Field><Field label="방향"><select value={rule.direction} onChange={(e)=>setRule({...rule,direction:e.target.value})}><option value="ingress">수신</option><option value="egress">송신</option></select></Field><Field label="프로토콜"><select value={rule.protocol} onChange={(e)=>setRule({...rule,protocol:e.target.value})}><option>tcp</option><option>udp</option><option>icmp</option></select></Field><Field label="포트"><div><input disabled={!['tcp','udp'].includes(rule.protocol)} value={rule.portMin} onChange={(e)=>setRule({...rule,portMin:e.target.value})}/><input disabled={!['tcp','udp'].includes(rule.protocol)} value={rule.portMax} onChange={(e)=>setRule({...rule,portMax:e.target.value})}/></div></Field><Field label="원격 CIDR"><input value={rule.remoteIpPrefix} onChange={(e)=>setRule({...rule,remoteIpPrefix:e.target.value})}/></Field><button className="primary-btn" disabled={busy}>규칙 추가</button></form></div>:null}<div className="mini-horizon-table">{snapshot.securityGroups.map((g)=><article key={g.id}><div><strong>{g.name}</strong><small>{g.description||g.id}</small></div><span className="status-chip is-muted">규칙 {(g.security_group_rules||[]).length}</span><SecurityRuleList rules={g.security_group_rules||[]} mutable={!['default','example.com'].includes(String(g.name||'').toLowerCase())} onDelete={(item)=>act('DELETE','/api/cloud-console/security-group-rules/'+item.id,{},'보안 규칙을 삭제합니다.')}/><div>{!["default","example.com"].includes(String(g.name||"").toLowerCase())?<><button className="mini-btn" onClick={()=>manageSecurityGroupRules(g)}>규칙 관리</button><button className="mini-btn danger-mini-btn" onClick={()=>act("DELETE","/api/cloud-console/security-groups/"+g.id,{},"보안그룹을 삭제합니다.")}>삭제</button></>:null}</div></article>)}</div></div>:null}
      {tab==="actions"?<div className="mini-horizon-content"><Toolbar title="작업 내역" onRefresh={()=>props.loadCloudConsoleActions?.()}/>{actions.length?<div className="mini-horizon-table">{actions.map((a)=><article key={a.id}><div><strong>{operationLabel(a.operation)}</strong><small>{new Date(a.createdAt).toLocaleString("ko-KR")} · {a.userName||a.username}</small></div><span className={"status-chip "+statusTone(a.status)}>{statusLabel(a.status)}</span><p>예상 월 비용 {won.format(a.estimatedMonthlyCost||0)}원 {a.errorMessage?"· "+a.errorMessage:""}</p><div>{props.isAdmin&&a.status==="requested"?<><button className="primary-mini-btn" disabled={busy} onClick={()=>props.reviewCloudConsoleAction?.(a.id,"approve")}>승인·실행</button><button className="mini-btn danger-mini-btn" disabled={busy} onClick={()=>props.reviewCloudConsoleAction?.(a.id,"reject")}>반려</button></>:null}</div></article>)}</div>:<Empty/>}</div>:null}
    </>}
  </section>;
}
